-- Database roles and grants for the "app" schema. Generated by `make roles`.
-- Apply as a role holding CREATEROLE, once, before the first `make migrate`.
-- Safe to re-apply, in one transaction, so no write is granted between statements.
-- Set the password for the application role out of band.
BEGIN;

-- app_owner: owns the schema, applies the DDL, serves nothing.
DO $app$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_owner') THEN
    CREATE ROLE app_owner NOLOGIN;
  END IF;
END
$app$;

-- app_app: what the application connects as. DML only, subject to every policy.
DO $app$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_app') THEN
    CREATE ROLE app_app LOGIN;
  END IF;
END
$app$;

-- The schema, owned so that the default privileges below actually bind.
CREATE SCHEMA IF NOT EXISTS "app" AUTHORIZATION app_owner;
GRANT USAGE ON SCHEMA "app" TO app_app;

-- Existing objects, for a schema that was migrated before these roles existed.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA "app" TO app_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA "app" TO app_app;
-- Except writes on the ledger, and all but inserts on the audit events.
DO $app$
BEGIN
  IF to_regclass('"app".applied_once') IS NOT NULL
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_app') THEN
    EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON "app".applied_once FROM %I', 'app_app');
  END IF;
END
$app$;
DO $app$
DECLARE
  writable name;
BEGIN
  IF to_regclass('"app".audit_events') IS NOT NULL
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_app') THEN
    EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON "app".audit_events FROM %I', 'app_app');
    FOR writable IN
      SELECT attname FROM pg_attribute
      WHERE attrelid = '"app".audit_events'::regclass AND attnum > 0 AND NOT attisdropped
        AND attname NOT IN ('seq', 'recorded_at')
    LOOP
      EXECUTE format('GRANT INSERT (%I) ON "app".audit_events TO %I', writable, 'app_app');
    END LOOP;
  END IF;
END
$app$;

-- Everything app_owner creates from here on. Without this, the table added by the
-- next migration is invisible to the application until somebody re-runs the GRANT.
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA "app"
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_app;
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA "app"
  GRANT USAGE, SELECT ON SEQUENCES TO app_app;

-- Every migration withholds the same writes, because this script, run before the
-- first one, finds no table to withhold them on. See app/store/migrate.py.
COMMIT;
